CREATE OR REPLACE FUNCTION trip_private.guard_generated_content() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_text text; BEGIN v_text:=CASE TG_TABLE_NAME WHEN 'game_cards' THEN to_jsonb(NEW)->>'prompt' WHEN 'weekly_question_pool' THEN to_jsonb(NEW)->>'prompt' WHEN 'at_home_pack_items' THEN coalesce(to_jsonb(NEW)->>'title','')||' '||coalesce(to_jsonb(NEW)->>'body','') WHEN 'content_variants' THEN to_jsonb(NEW)->>'text' WHEN 'security_missions' THEN coalesce(to_jsonb(NEW)->>'title','')||' '||coalesce(to_jsonb(NEW)->>'text','') ELSE '' END; IF NOT trip_private.content_text_safe(v_text) THEN RAISE EXCEPTION 'Content did not pass the safety check'; END IF; RETURN NEW; END $$;